class UserAction @Inject() (val parser: BodyParsers.Default)(implicit val ec: ExecutionContext)
    extends ActionBuilder[UserRequest, AnyContent]
    with ActionTransformer[Request, UserRequest] {
  def transform[A](request: Request[A]) = Future.successful(new UserRequest(request.session.get("user"), request))
}

def PermissionCheckAction(implicit ec: ExecutionContext) = new ActionFilter[ItemRequest] {
  def filter[A](input: ItemRequest[A]) =
    Future.successful(if (input.item.accessibleByUser(input.user)) None else Some(Forbidden))
}

def tagItem(id: String) = userAction.andThen(ItemAction(id)).andThen(PermissionCheckAction) { req => ... }
